  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is teleoperation data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the recording of robot demonstrations while a human operator controls the robot remotely through a leader arm, VR controller, 3D mouse, or haptic device. The robot logs its own joint states, camera streams, and commanded actions, producing training data in its native action space for imitation learning and VLA models."
        }
      },
      {
        "@type": "Question",
        "name": "How many teleoperation demonstrations do I need to train a policy?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It depends on task scope. Mobile ALOHA reached strong results with 50 demonstrations per task plus co-training data, while generalist datasets like DROID used 76,000 trajectories. We recommend a 50 to 200 episode pilot per task and a baseline training run before scaling."
        }
      },
      {
        "@type": "Question",
        "name": "Is teleoperation better than human video for robot learning?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Teleop data is already in the robot's action space, so it trains policies directly. Human video is cheaper to scale but needs retargeting to the robot body. Many teams pretrain on video and fine-tune on teleop episodes recorded on their own hardware."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect teleop data on our robots at our site?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We can deploy operators and rigs to your facility, record on robots in our own collection cell, or run a mix. Site work starts with a calibration and safety review of your hardware."
        }
      },
      {
        "@type": "Question",
        "name": "Which teleop interface should we use: VR, leader arm, or 3D mouse?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Leader-follower arms give the best joint-space fidelity for bimanual and dynamic tasks. VR suits end-effector control and mobile manipulation. A 3D mouse works for slow, precise positioning. Haptic devices fit contact-rich tasks. We often pair two interfaces on one program."
        }
      },
      {
        "@type": "Question",
        "name": "How do you check teleop data quality before delivery?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Every episode is scored for task success, trajectory smoothness, calibration drift, annotation consistency, and environment coverage. Programs also pass our Inference Parity Audit, which checks that operators only used information the policy will have at inference."
        }
      },
      {
        "@type": "Question",
        "name": "How long does a teleop pilot take?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Most pilots are scoped in weeks rather than months. Timeline depends on hardware access, how many tasks are in scope, and whether we build a new rig or use an existing one. You get a pilot batch and a learnability check before any volume commitment."
        }
      }
    ]
  }
